-- Testimonials from colleagues and clients

create table "public"."testimonials" (
  "id" bigint primary key generated by default as identity,
  "text" text,
  "person" varchar,
  "image" varchar,
  "at" varchar,
  "user" uuid,
  "order" smallint,
  "role" varchar,
  "is_active" boolean not null default true
);

alter table "public"."testimonials" add constraint "testimonials_user_fkey" foreign key ("user") references auth.users (id) on update cascade on delete cascade;

alter table "public"."testimonials" enable row level security;
create policy "Enable read access for all users" on "public"."testimonials" for select using (true);

grant all on "public"."testimonials" to postgres, anon, authenticated, service_role;
